import { Request, Response } from "express";
import Redis from "ioredis";

const redis = new Redis(process.env.REDIS_URL);

// Single global key holding every place in the entire dataset, regardless of city/region.
const LOCATIONS_KEY = "locations";

/**
 * Called whenever a place is created/updated anywhere in the system.
 * Every point, no matter which city it belongs to, lands in the same GEO key.
 */
export async function indexPlace(placeId: string, lng: number, lat: number): Promise<void> {
  await redis.geoadd(LOCATIONS_KEY, lng, lat, placeId);
}

function haversineKm(lat1: number, lng1: number, lat2: number, lng2: number): number {
  const toRad = (deg: number) => (deg * Math.PI) / 180;
  const R = 6371;
  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) ** 2;
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
}

interface NearbyPlace {
  placeId: string;
  distanceKm: number;
}

/**
 * GET /places/nearby?lat=..&lng=..&radiusKm=..
 */
export async function findNearby(req: Request, res: Response): Promise<void> {
  const lat = Number(req.query.lat);
  const lng = Number(req.query.lng);
  const radiusKm = Number(req.query.radiusKm);

  // Pull every member of the global key back to the app first.
  const allPlaceIds = await redis.zrange(LOCATIONS_KEY, 0, -1);

  if (allPlaceIds.length === 0) {
    res.json({ results: [] });
    return;
  }

  // Then fetch coordinates for every single one of them.
  const positions = await redis.geopos(LOCATIONS_KEY, ...allPlaceIds);

  const candidates: NearbyPlace[] = [];
  for (let i = 0; i < allPlaceIds.length; i++) {
    const pos = positions[i];
    if (!pos) continue;

    const placeLng = Number(pos[0]);
    const placeLat = Number(pos[1]);

    // Distance math done in the application, point by point.
    const distanceKm = haversineKm(lat, lng, placeLat, placeLng);
    if (distanceKm <= radiusKm) {
      candidates.push({ placeId: allPlaceIds[i], distanceKm });
    }
  }

  // Sort survivors by distance in JS after the fact.
  candidates.sort((a, b) => a.distanceKm - b.distanceKm);

  res.json({ results: candidates });
}
